/* Editable 2D CAD export in the original EPSG:5179 plane, drawing units metres. */
function buildLayoutDxf(layout,count){
  const g=layout.cadGeometry;
  if(!g||g.crs!=='EPSG:5179'||g.units!=='m')throw Error('CAD 좌표가 없는 이전 배치입니다. 다시 그리기를 누른 뒤 다운로드하세요.');
  if(!Number.isInteger(count)||count<0||count>g.panels.length)throw Error('모듈 수량을 확인하세요.');
  const pairs=[],put=(code,value)=>pairs.push(String(code),String(value));
  const num=v=>{if(!Number.isFinite(v))throw Error('도면 좌표를 확인할 수 없습니다.');return v.toFixed(6)};
  const ascii=s=>String(s).replace(/[\r\n]/g,' ').replace(/[^\x20-\x7e]/g,c=>'\\U+'+c.charCodeAt(0).toString(16).toUpperCase().padStart(4,'0'));
  let handle=256;const next=()=> (++handle).toString(16).toUpperCase();
  const points=g.outlines.flatMap(p=>p.flat());
  if(!points.length)throw Error('부지 경계가 없습니다.');
  const xmin=Math.min(...points.map(p=>p[0])),xmax=Math.max(...points.map(p=>p[0])),ymin=Math.min(...points.map(p=>p[1])),ymax=Math.max(...points.map(p=>p[1]));
  const CAD_DXF_TEMPLATE=CAD_DXF_TEMPLATES.find(t=>xmax-xmin<=t.width-40&&ymax-ymin+40<=t.height-60)||CAD_DXF_TEMPLATES.at(-1);
  const header=CAD_DXF_TEMPLATE.prefix.slice();
  function setEntity(handle,code,value){let at=header.findIndex((v,i)=>i%2===0&&v==='5'&&header[i+1]===handle);if(at<0)throw Error('CAD 뷰 설정을 확인하세요.');for(let i=at+2;i<header.length&&header[i]!=='0';i+=2){if(header[i]===String(code)){header[i+1]=String(value);return}}throw Error('CAD 뷰 속성이 없습니다.');}
  const cx=(xmin+xmax)/2,cy=(ymin+ymax)/2+10;
  setEntity(CAD_DXF_TEMPLATE.viewport,12,num(cx));setEntity(CAD_DXF_TEMPLATE.viewport,22,num(cy));
  setEntity(CAD_DXF_TEMPLATE.active,12,num(cx));setEntity(CAD_DXF_TEMPLATE.active,22,num(cy));setEntity(CAD_DXF_TEMPLATE.active,40,num(Math.max(ymax-ymin+50,(xmax-xmin+50)/1.5)));

  function setHeader(name,values){const at=header.findIndex((v,i)=>i%2===0&&v==='9'&&header[i+1]===name);if(at<0)throw Error('DXF 기본 도면을 확인하세요.');for(let j=0;j<values.length;j++)header[at+3+j*2]=String(values[j])}
  setHeader('$EXTMIN',[num(xmin),num(ymin),0]);setHeader('$EXTMAX',[num(xmax),num(ymax+20),0]);setHeader('$HANDSEED',['1000000']);
  pairs.push(...header);
  function polygon(ring,layer){
    let pts=ring.slice();if(pts.length>1&&pts[0][0]===pts.at(-1)[0]&&pts[0][1]===pts.at(-1)[1])pts.pop();
    if(pts.length<3)throw Error('도면 경계의 점이 부족합니다.');
    put(0,'LWPOLYLINE');put(5,next());put(330,CAD_DXF_TEMPLATE.owner);put(100,'AcDbEntity');put(8,layer);put(100,'AcDbPolyline');put(90,pts.length);put(70,1);
    for(const p of pts){put(10,num(p[0]));put(20,num(p[1]))}
  }
  for(const rings of g.outlines)rings.forEach((r,i)=>polygon(r,i?'SITE_HOLE':'SITE_BOUNDARY'));
  for(const panel of g.panels.slice(0,count))polygon(panel,'PV_MODULE');
  const notes=[
    'SOLAR_JIN / CONCEPT LAYOUT / NOT A SURVEY OR CONSTRUCTION DRAWING',
    'PRINT LAYOUT: PRINT_1_1000 / SCALE 1:1000 / PAPER '+CAD_DXF_TEMPLATE.paper+' / PRINT PAPER SPACE AT 1:1',
    'CRS EPSG:5179 / X Easting, Y Northing / 1 drawing unit = 1 metre / 2D plan projection',
    `MODULE ${g.moduleLengthMm} x ${g.moduleWidthMm} mm / ${g.moduleWp} Wp / COUNT ${count} / DC ${(count*g.moduleWp/1000).toFixed(3)} kWp`,
    `TILT ${g.tiltDeg} deg from horizontal / TIERS ${g.tiers} / SOLAR ALTITUDE 25 deg / SOUTH FACING`,
    `ROW CLEAR GAP ${g.rowGapM.toFixed(4)} m / ROW PITCH ${g.rowPitchM.toFixed(4)} m / SITE SETBACK ${g.boundarySetbackM??layout.boundarySetbackMm/1000} m`,
    'DEM REPRESENTATIVE TERRAIN / VERIFY BOUNDARIES AND FIELD OBSTACLES / SATELLITE IMAGE NOT EMBEDDED',
    'PNU '+(layout.pnus||[]).join(', ')
  ];
  notes.forEach((text,i)=>{put(0,'TEXT');put(5,next());put(330,CAD_DXF_TEMPLATE.owner);put(100,'AcDbEntity');put(8,'DESIGN_NOTES');put(100,'AcDbText');put(10,num(xmin));put(20,num(ymax+18-i*2.5));put(30,0);put(40,1);put(1,ascii(text));put(50,0);put(100,'AcDbText')});
  pairs.push(...CAD_DXF_TEMPLATE.suffix);return pairs.join('\r\n')+'\r\n';
}
function downloadLayoutDxf(){
  try{
    const layout=currentCombinedLayout(unique().ps);
    if(layout?.status!=='ok')throw Error('배치를 완료한 뒤 다운로드하세요.');
    const tiers=+state.moduleTiers||1;
    const count=Math.min(layout.count,+state.capLimit>0?Math.floor(+state.capLimit/(layout.moduleWp/1000)/tiers+1e-8)*tiers:layout.count);
    const content=buildLayoutDxf(layout,count),blob=new Blob([content],{type:'application/dxf'}),url=URL.createObjectURL(blob),link=document.createElement('a');
    link.href=url;link.download='SOLAR_JIN_'+(layout.pnu||'layout')+'_'+count+'modules_1-1000.dxf';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }catch(error){alert(error.message)}
}
let cadPackageBusy=false;
async function downloadCadWithSatellite(button){
  if(cadPackageBusy)return;
  const original=button.textContent;
  try{
    const layout=currentCombinedLayout(unique().ps);
    if(layout?.status!=='ok'||!layout.cadToken)throw Error('배치도에서 다시 그리기를 누르고 완료 후 다운로드하세요.');
    const tiers=+state.moduleTiers||1;
    const count=Math.min(layout.count,+state.capLimit>0?Math.floor(+state.capLimit/(layout.moduleWp/1000)/tiers+1e-8)*tiers:layout.count);
    cadPackageBusy=true;button.disabled=true;button.textContent='사진과 CAD를 묶는 중…';
    const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),180000);
    try{
      const response=await fetch('/api/cad-package',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:layout.cadToken,count}),signal:controller.signal});
      if(!response.ok){const data=await response.json();throw Error(data.error||'다운로드에 실패했습니다.')}
      const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='SOLAR_JIN_'+layout.pnu+'_'+count+'modules_CAD_satellite.zip';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
    }finally{clearTimeout(timer)}
  }catch(error){alert(error.name==='AbortError'?'위성사진 작성이 지연됩니다. 잠시 후 다시 시도하세요.':error.message)}
  finally{cadPackageBusy=false;button.disabled=false;button.textContent=original}
}
document.addEventListener('click',event=>{const photo=event.target.closest?.('[data-cad-satellite]');if(photo){downloadCadWithSatellite(photo);return}if(event.target.closest?.('[data-cad-download]'))downloadLayoutDxf()});
